# Generated by Claude
"""Self-test for the commit window's non-GUI half.

Follows the convention of the sibling tools (ValueCheck's `selftest_*.py`):
one script, no framework, run it and read the last line.

    python tools\\selftest_commitgui.py

It builds a throwaway repository in the temp directory and exercises the
things that are easy to get wrong and invisible until they bite:

* CJK and spaces in filenames, end to end -- porcelain parsing, grouping,
  pathspec files, and the commit that comes out the other side.
* Front matter titles in every shape the repo actually contains.
* Grouping, including the "no file is ever dropped" property, which is
  checked by counting rather than by inspection.
* Regenerating a message after a file is unticked.

Nothing here touches the blog repository.
"""
from __future__ import annotations

import os
import shutil
import subprocess
import sys
import tempfile

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from commitgui import gitcmd, model, rules
from commitgui.workers import CommitWorker

FAILURES: list[str] = []
CHECKS = 0


def check(condition, label, detail=""):
    global CHECKS
    CHECKS += 1
    if not condition:
        FAILURES.append(f"{label}{(': ' + detail) if detail else ''}")
        print(f"  FAIL  {label}{(': ' + detail) if detail else ''}")
    else:
        print(f"  ok    {label}")


def equal(got, want, label):
    check(got == want, label, f"got {got!r}, want {want!r}")


# ── pure functions ────────────────────────────────────────────────────────

def test_effective_status():
    print("\n[status codes]")
    cases = {
        ("?", "?"): "A", ("A", " "): "A", ("A", "M"): "A",
        ("M", " "): "M", (" ", "M"): "M", ("M", "M"): "M",
        ("D", " "): "D", (" ", "D"): "D",
        ("U", "U"): "U", ("A", "A"): "U", ("D", "U"): "U",
        ("!", "!"): "!",
    }
    for (x, y), want in cases.items():
        equal(model._effective_status(x, y), want, f"{x}{y} -> {want}")


def test_porcelain_parse():
    print("\n[porcelain parsing]")
    raw = (b"?? _posts/2026-9-5-\xe6\x96\xb0\xe4\xb9\xa6 \xe5\x90\x8d.md\0"
           b" M _config.yml\0"
           b"A  images/a b.png\0"
           b"!! _site/\0")
    got = list(model._parse_porcelain(raw))
    equal(len(got), 4, "four records")
    equal(got[0][2], "_posts/2026-9-5-新书 名.md", "CJK + space path")
    equal(got[1], (" ", "M", "_config.yml"), "unstaged: X blank, Y=M")
    equal(got[2], ("A", " ", "images/a b.png"), "staged add: X=A, Y blank")
    equal(got[3][0], "!", "ignored marker")
    # A record shorter than "XY p" must be skipped, not crash.
    equal(list(model._parse_porcelain(b"\0??\0")), [], "short records skipped")


def test_front_matter():
    print("\n[front matter titles]")
    samples = [
        ("---\nlayout: post\ntitle:  What I Learned\ncategories: [x]\n---\nbody",
         "What I Learned", "two spaces after colon (repo's own style)"),
        ('---\ntitle: "Quoted Title"\n---\n', "Quoted Title", "double quotes"),
        ("---\ntitle: '单引号标题'\n---\n", "单引号标题", "single quotes, CJK"),
        ("﻿---\ntitle: With BOM\n---\n", "With BOM", "leading BOM"),
        ("no front matter here", "", "no front matter"),
        ("---\nlayout: post\n---\n", "", "front matter without title"),
        ("---\ntitle: Trailing   \n---\n", "Trailing", "trailing whitespace"),
    ]
    for text, want, label in samples:
        equal(rules._front_matter_title(text), want, label)


